const OWNED_CONTROL_DATA=new Set([
'data-state','data-on','data-enhanced','data-open','data-side',
'data-active','data-status','data-floated','data-collapsible',
'data-filled','data-orientation',
]);
export function customizeControlPart(part,defaultClass,ownedStyle,extraClass){
if(!part)
return{};
const result={};
for(const[key,value]of Object.entries(part)){
if(/^data-[a-z][a-z0-9-]*$/.test(key)&&
!OWNED_CONTROL_DATA.has(key)&&
(typeof value==='string'||typeof value==='number'||typeof value==='boolean')){
result[key]=value;
}
}
if(typeof part.title==='string')
result.title=part.title;
if(part.style&&typeof part.style==='object'){
result.style=ownedStyle?{...part.style,...ownedStyle}:{...part.style};
}
const classes=[defaultClass,extraClass,part.className].filter((v)=>typeof v==='string'&&v.length>0);
if(classes.length)
result.className=classes.join(' ');
return result;
}
